19	        "id": "refuted-first",
20	        "rule": "案を複数出して反証し、残った1つだけを答えに書く。除外した案は rejected に残す。",
21	        "why": "並べて選ばせると、判断を利用者に移すことになる。",
22	        "test": "rejected が1件以上あるかを見る。"
23	      }
24	    ]
25	  },
