{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "x-abstract": "schema-driven/abstract@v1",
  "$id": "brainstorming/board@v1",
  "title": "ボード",
  "description": "決めることがある問いを論点に分け、反証で絞った答えを承認だけで決められるようにする1枚。本体は .brainstorming/<id>.json に置き、回の記録 ・ 回答 ・ 図は .brainstorming/<id>/ に置く。",
  "x-prompt": {
    "read": {
      "means": "1枚のボードである。論点はこの中のエンティティで、回答と回の記録は別のインスタンスが持つ。"
    },
    "write": [
      {
        "id": "decisions-only",
        "rule": "利用者に渡すのは決定だけにし、事実は調べて根拠に書く。",
        "why": "事実を聞くと、承認ではなく調べものを利用者に任せることになる。",
        "test": "問いに、調べれば分かることが入っていないかを見る。"
      },
      {
        "id": "refuted-first",
        "rule": "案を複数出して反証し、残った1つだけを答えに書く。除外した案は rejected に残す。",
        "why": "並べて選ばせると、判断を利用者に移すことになる。",
        "test": "rejected が1件以上あるかを見る。"
      }
    ]
  },
  "x-generates": ".brainstorming/<ボード>.json",
  "x-view": {
    "label": "{title}"
  },
  "type": "object",
  "additionalProperties": false,
  "required": [
    "$schema",
    "kind",
    "id",
    "title",
    "status",
    "round",
    "topics"
  ],
  "properties": {
    "$schema": {
      "description": "従うスキーマの名前",
      "x-prompt": {
        "read": {
          "means": "このインスタンスが従う型の名前である。"
        },
        "write": [
          {
            "id": "this-name",
            "rule": "brainstorming/board@v1 と書く。",
            "why": "エンジンは、この名前で型のスキーマを引く。",
            "test": "値がこの文字列と同じかを見る。"
          }
        ]
      },
      "const": "brainstorming/board@v1"
    },
    "kind": {
      "description": "インスタンスの種類",
      "x-prompt": {
        "read": {
          "means": "このインスタンスの種類である。"
        },
        "write": [
          {
            "id": "const",
            "rule": "board と書く。",
            "why": "ページテンプレートと参照は kind で選ぶ。",
            "test": "値が同じかを見る。"
          }
        ]
      },
      "const": "board"
    },
    "id": {
      "description": "ボードの名前。ファイル名と同じ",
      "x-prompt": {
        "read": {
          "means": "ボードの名前である。"
        },
        "write": [
          {
            "id": "file-name",
            "rule": ".brainstorming/<id>.json のファイル名と同じにする。",
            "why": "サイドバーとダッシュボードは id でボードを指す。",
            "test": "ファイル名と同じかを見る。"
          }
        ]
      },
      "type": "string",
      "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
    },
    "title": {
      "description": "題",
      "x-prompt": {
        "read": {
          "means": "ボードが何を決めるかの短い題である。"
        },
        "write": [
          {
            "id": "short",
            "rule": "40字くらいまでの名詞句で書く。",
            "why": "サイドバーに並ぶ。",
            "test": "40字を超えていないかを見る。"
          }
        ]
      },
      "type": "string",
      "minLength": 1
    },
    "intro": {
      "description": "このボードが何を決めるかの1文",
      "x-prompt": {
        "read": {
          "means": "ボードの目的である。"
        },
        "write": [
          {
            "id": "one-sentence",
            "rule": "何を決めるかを1文で書く。決まったことの一覧は書かない。",
            "why": "論点の一覧と重なる。",
            "test": "1文かを見る。"
          }
        ]
      },
      "type": "string",
      "minLength": 1
    },
    "status": {
      "description": "ボードの状態",
      "x-prompt": {
        "read": {
          "means": "いま答える ・ 進行中 ・ 保留 ・ 決着のどれかである。"
        },
        "write": [
          {
            "id": "by-queue",
            "rule": "いま答える論点があれば answer、AI が組み直しているあいだは working、止めているなら hold、論点がすべて決着したら done にする。",
            "why": "サイドバーとダッシュボードはこの値でまとめる。",
            "test": "answer なのに queue が空でないか、done なのに決着していない論点が無いかを見る。"
          }
        ]
      },
      "enum": [
        "answer",
        "working",
        "hold",
        "done"
      ]
    },
    "flag": {
      "description": "優先の印",
      "x-prompt": {
        "read": {
          "means": "先に決めてほしいボードの印である。"
        },
        "write": [
          {
            "id": "rare",
            "rule": "ほかの作業を止めているときだけ true にする。",
            "why": "全部に付けると印にならない。",
            "test": "true のボードが少数かを見る。"
          }
        ]
      },
      "type": "boolean"
    },
    "waits_for": {
      "description": "このボードが答えを待っているほかのボード",
      "x-prompt": {
        "read": {
          "means": "このボードの答えが前提にしているほかのボードである。"
        },
        "write": [
          {
            "id": "by-id",
            "rule": "ほかのボードの id を書く。",
            "why": "ダッシュボードは、待たれている数で先に決めるものを並べる。",
            "test": "指す先のボードがあるかを check で見る。"
          }
        ]
      },
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
      },
      "uniqueItems": true,
      "x-ref": {
        "to": "board"
      }
    },
    "round": {
      "description": "いまの回の番号",
      "x-prompt": {
        "read": {
          "means": "いま出している回である。"
        },
        "write": [
          {
            "id": "by-advance",
            "rule": "advance が書く。手で書き換えない。",
            "why": "回の記録の番号と合わなくなる。",
            "test": "rounds/ の最後の番号と同じかを見る。"
          }
        ]
      },
      "type": "integer",
      "minimum": 1
    },
    "opened": {
      "description": "いまの回を出した日",
      "x-prompt": {
        "read": {
          "means": "回答を待ち始めた日である。"
        },
        "write": [
          {
            "id": "by-advance",
            "rule": "advance が書く。",
            "why": "ダッシュボードは、回答を待っている日数をここから数える。",
            "test": "日付の形かを見る。"
          }
        ]
      },
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
    },
    "queue": {
      "description": "いま見る論点と、なぜいま開いたか",
      "x-prompt": {
        "read": {
          "means": "いま答えてほしい論点の並びである。"
        },
        "write": [
          {
            "id": "ready-only",
            "rule": "前提が片付いた論点だけを並べ、なぜいま開いたかを1文で書く。",
            "why": "前提が開いている論点に答えると、あとで覆る。",
            "test": "並べた論点の depends がすべて決着しているかを見る。"
          }
        ]
      },
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "topic",
          "why"
        ],
        "properties": {
          "topic": {
            "type": "string",
            "pattern": "^Q[0-9]+$",
            "description": "論点の id",
            "x-ref": {
              "to": "self",
              "in": "topics",
              "bare": true
            },
            "x-prompt": {
              "read": {
                "means": "論点の idである。"
              },
              "write": [
                {
                  "id": "as-described",
                  "rule": "説明のとおりに書く。",
                  "why": "読み手と道具は説明のとおりに読む。",
                  "test": "説明と合っているかを見る。"
                }
              ]
            }
          },
          "why": {
            "type": "string",
            "minLength": 1,
            "description": "なぜいま開いたか",
            "x-prompt": {
              "read": {
                "means": "なぜいま開いたかである。"
              },
              "write": [
                {
                  "id": "as-described",
                  "rule": "説明のとおりに書く。",
                  "why": "読み手と道具は説明のとおりに読む。",
                  "test": "説明と合っているかを見る。"
                }
              ]
            }
          }
        }
      }
    },
    "changes": {
      "description": "この回で変わったところ",
      "x-prompt": {
        "read": {
          "means": "前の回から変わったところと、その理由である。"
        },
        "write": [
          {
            "id": "by-advance",
            "rule": "advance が、前の回と比べて書く。理由には差し戻しの言葉をそのまま入れる。",
            "why": "どこを直したかを書き手が文章で言うのは、仕組みではない。",
            "test": "前の回の記録と比べて、変わった欄だけが並んでいるかを見る。"
          }
        ]
      },
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "topic",
          "part",
          "summary"
        ],
        "properties": {
          "topic": {
            "type": "string",
            "pattern": "^Q[0-9]+$",
            "description": "論点の id",
            "x-ref": {
              "to": "self",
              "in": "topics",
              "bare": true
            },
            "x-prompt": {
              "read": {
                "means": "論点の idである。"
              },
              "write": [
                {
                  "id": "as-described",
                  "rule": "説明のとおりに書く。",
                  "why": "読み手と道具は説明のとおりに読む。",
                  "test": "説明と合っているかを見る。"
                }
              ]
            }
          },
          "part": {
            "enum": [
              "question",
              "answer",
              "details",
              "images",
              "assumptions",
              "checks",
              "grounds",
              "rejected",
              "status",
              "added"
            ],
            "description": "変わった欄",
            "x-prompt": {
              "read": {
                "means": "変わった欄である。"
              },
              "write": [
                {
                  "id": "as-described",
                  "rule": "説明のとおりに書く。",
                  "why": "読み手と道具は説明のとおりに読む。",
                  "test": "説明と合っているかを見る。"
                }
              ]
            }
          },
          "summary": {
            "type": "string",
            "minLength": 1,
            "description": "何が変わったかの1文",
            "x-prompt": {
              "read": {
                "means": "何が変わったかの1文である。"
              },
              "write": [
                {
                  "id": "as-described",
                  "rule": "説明のとおりに書く。",
                  "why": "読み手と道具は説明のとおりに読む。",
                  "test": "説明と合っているかを見る。"
                }
              ]
            }
          },
          "reason": {
            "type": "string",
            "minLength": 1,
            "description": "なぜ変えたか（差し戻しの言葉）",
            "x-prompt": {
              "read": {
                "means": "なぜ変えたか（差し戻しの言葉）である。"
              },
              "write": [
                {
                  "id": "as-described",
                  "rule": "説明のとおりに書く。",
                  "why": "読み手と道具は説明のとおりに読む。",
                  "test": "説明と合っているかを見る。"
                }
              ]
            }
          }
        }
      }
    },
    "log": {
      "description": "最近の動き",
      "x-prompt": {
        "read": {
          "means": "このボードで起きたことの記録である。"
        },
        "write": [
          {
            "id": "append",
            "rule": "新しいものを先頭に足す。",
            "why": "ダッシュボードは先頭から読む。",
            "test": "日付が新しい順かを見る。"
          }
        ]
      },
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "date",
          "text"
        ],
        "properties": {
          "date": {
            "type": "string",
            "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$",
            "x-prompt": {
              "read": {
                "means": "dateである。"
              },
              "write": [
                {
                  "id": "as-described",
                  "rule": "説明のとおりに書く。",
                  "why": "読み手と道具は説明のとおりに読む。",
                  "test": "説明と合っているかを見る。"
                }
              ]
            }
          },
          "text": {
            "type": "string",
            "minLength": 1,
            "x-prompt": {
              "read": {
                "means": "textである。"
              },
              "write": [
                {
                  "id": "only-needed",
                  "rule": "見せたい部分だけを書く。",
                  "why": "長いと強調した行が埋もれる。",
                  "test": "60行くらいまでかを見る。"
                }
              ]
            }
          }
        }
      }
    },
    "topics": {
      "description": "論点の並び",
      "x-prompt": {
        "read": {
          "means": "このボードの論点である。"
        },
        "write": [
          {
            "id": "three-to-five",
            "rule": "3〜5件にし、依存の順に並べる。",
            "why": "多すぎると決着しないまま依存が増える。",
            "test": "件数を見る。"
          }
        ]
      },
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/topic"
      }
    }
  },
  "$defs": {
    "topic": {
      "type": "object",
      "additionalProperties": false,
      "description": "論点1つ",
      "x-prompt": {
        "read": {
          "means": "決めることを1つ持つ論点である。"
        },
        "write": [
          {
            "id": "one-decision",
            "rule": "1つの論点で決めることを1つにする。",
            "why": "2つを1つの論点で決めると、片方だけを差し戻せない。",
            "test": "答えの1文が1つのことを決めているかを見る。"
          }
        ]
      },
      "required": [
        "id",
        "name",
        "status",
        "question",
        "answer"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^Q[0-9]+$",
          "description": "論点の id（Q0 ・ Q1 …）",
          "x-prompt": {
            "read": {
              "means": "論点の id（Q0 ・ Q1 …）である。"
            },
            "write": [
              {
                "id": "unique",
                "rule": "ボードの中で重ならない id を書く。",
                "why": "回答と変わったところは id で論点を指す。",
                "test": "重なりが無いかを見る。"
              }
            ]
          }
        },
        "name": {
          "type": "string",
          "minLength": 1,
          "description": "論点の短い名前",
          "x-prompt": {
            "read": {
              "means": "論点の短い名前である。"
            },
            "write": [
              {
                "id": "short",
                "rule": "10字くらいの名前を書く。",
                "why": "タブに並ぶ。",
                "test": "長すぎないかを見る。"
              }
            ]
          }
        },
        "status": {
          "enum": [
            "waiting",
            "open",
            "settled"
          ],
          "description": "前提待ち ・ いま答える ・ 決着",
          "x-prompt": {
            "read": {
              "means": "前提待ち ・ いま答える ・ 決着である。"
            },
            "write": [
              {
                "id": "by-flow",
                "rule": "前提が片付いていなければ waiting、いま答えるなら open、承認されたら settled にする。",
                "why": "画面は open の論点にだけ回答欄を出す。",
                "test": "queue と合っているかを見る。"
              }
            ]
          }
        },
        "question": {
          "type": "string",
          "minLength": 1,
          "description": "問い",
          "x-prompt": {
            "read": {
              "means": "問いである。"
            },
            "write": [
              {
                "id": "decidable",
                "rule": "答えが1つに決まる問いを書く。",
                "why": "広すぎる問いは承認で決められない。",
                "test": "答えの1文が問いに答えているかを見る。"
              }
            ]
          }
        },
        "answer": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "text"
          ],
          "description": "答え",
          "properties": {
            "text": {
              "type": "string",
              "minLength": 1,
              "description": "承認してほしいことの1文",
